package com.busycall.app.bridge

/**
 * Where a phone number is from. [regions] are US state / Canadian province codes ("OH",
 * "NS", "PE") that the map can show; empty for other countries.
 */
data class Place(val name: String, val regions: List<String> = emptyList())

/**
 * Finds a number's place: North American numbers by area code (state / province, or the
 * Caribbean country), others by country calling code. The area code says where the number was
 * issued, not where the caller is. Pure; data from assets/bc_area_codes.csv and bc_regions.csv
 * (generated by tools/area-codes).
 */
class NumberPlaces(
    /** area code → "OH", "NS/PE" or a country name. */
    private val areaCodes: Map<String, String>,
    /** "OH" → "Ohio". */
    private val regionNames: Map<String, String>,
) {

    fun of(peerUri: String): Place? {
        val number = PeerName.phoneNumber(peerUri) ?: return null
        val digits = number.filter { it.isDigit() }
        val international = when {
            number.startsWith("+") -> digits
            digits.startsWith("011") -> digits.substring(3)
            digits.length == 10 -> "1$digits"
            digits.length == 11 && digits.startsWith("1") -> digits
            else -> return null // an extension or a short code
        }
        if (international.startsWith("1")) {
            if (international.length != 11) return null
            val region = areaCodes[international.substring(1, 4)] ?: return null
            val codes = region.split('/')
            if (codes.all { it in regionNames }) {
                return Place(codes.joinToString(" / ") { regionNames.getValue(it) }, codes)
            }
            return Place(region)
        }
        return CountryCodes.of(international)?.let { Place(it) }
    }

    companion object {
        val EMPTY = NumberPlaces(emptyMap(), emptyMap())

        /** Reads the two CSV files (`#` lines are comments). */
        fun parse(areaCodesCsv: String, regionsCsv: String) = NumberPlaces(pairs(areaCodesCsv), pairs(regionsCsv))

        private fun pairs(csv: String): Map<String, String> = csv.lineSequence()
            .map { it.trim() }
            .filter { it.isNotEmpty() && !it.startsWith("#") && ',' in it }
            .associate { it.substringBefore(',') to it.substringAfter(',') }
    }
}

/** Country calling codes outside North America, longest match first. */
object CountryCodes {
    private val names = mapOf(
        "20" to "Egypt", "27" to "South Africa", "30" to "Greece", "31" to "Netherlands",
        "32" to "Belgium", "33" to "France", "34" to "Spain", "36" to "Hungary", "39" to "Italy",
        "40" to "Romania", "41" to "Switzerland", "43" to "Austria", "44" to "United Kingdom",
        "45" to "Denmark", "46" to "Sweden", "47" to "Norway", "48" to "Poland", "49" to "Germany",
        "51" to "Peru", "52" to "Mexico", "53" to "Cuba", "54" to "Argentina", "55" to "Brazil",
        "56" to "Chile", "57" to "Colombia", "58" to "Venezuela", "60" to "Malaysia",
        "61" to "Australia", "62" to "Indonesia", "63" to "Philippines", "64" to "New Zealand",
        "65" to "Singapore", "66" to "Thailand", "7" to "Russia or Kazakhstan", "81" to "Japan",
        "82" to "South Korea", "84" to "Vietnam", "86" to "China", "90" to "Turkey", "91" to "India",
        "92" to "Pakistan", "93" to "Afghanistan", "94" to "Sri Lanka", "95" to "Myanmar",
        "98" to "Iran", "212" to "Morocco", "213" to "Algeria", "216" to "Tunisia", "234" to "Nigeria",
        "233" to "Ghana", "254" to "Kenya", "255" to "Tanzania", "256" to "Uganda", "251" to "Ethiopia",
        "351" to "Portugal", "353" to "Ireland", "354" to "Iceland", "358" to "Finland",
        "380" to "Ukraine", "420" to "Czech Republic", "421" to "Slovakia", "502" to "Guatemala",
        "503" to "El Salvador", "504" to "Honduras", "505" to "Nicaragua", "506" to "Costa Rica",
        "507" to "Panama", "509" to "Haiti", "591" to "Bolivia", "593" to "Ecuador",
        "595" to "Paraguay", "598" to "Uruguay", "852" to "Hong Kong", "880" to "Bangladesh",
        "886" to "Taiwan", "961" to "Lebanon", "962" to "Jordan", "966" to "Saudi Arabia",
        "971" to "United Arab Emirates", "972" to "Israel", "977" to "Nepal",
    )

    fun of(international: String): String? =
        (3 downTo 1).firstNotNullOfOrNull { n -> international.takeIf { it.length > n }?.let { names[it.take(n)] } }
}
